#!/usr/bin/env python3
"""Turn a 4x4 sprite sheet (e.g. generated by ChatGPT on a magenta background)
into a ready-to-build pet: animations.xml (desktopPet schema) + icon.png + preview.gif + sprite_preview.png.

usage: sheet2pet.py <sheet.png> <outdir> [--name NAME] [--cell 96] [--bg auto|#RRGGBB]

Frame layout (row-major, see prompts/spritesheet_prompt.md):
   0-3   walk cycle, facing RIGHT
   4-7   idle (standing, small motion / blink)
   8-9   sleeping      10-11 happy / jump
  12-13  being picked up (dangling)      14-15 falling

The script removes the background (only regions connected to the image border, so
colours inside the character are kept), crops/scales all frames with ONE common
scale, aligns feet to a common baseline, and writes the animation set. Exit code 2
means the sheet failed the quality checks (the messages say which frames to redo).
"""
import argparse
import os
import sys

sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from xmlgen import build_xml

import numpy as np
from PIL import Image
from scipy import ndimage

GRID = 4
FRAMES = GRID * GRID


# ------------------------------------------------------------------ background

def parse_color(s):
    s = s.lstrip("#")
    return tuple(int(s[i:i + 2], 16) for i in (0, 2, 4))


def estimate_bg(rgb):
    """Median colour of the outer 3px frame of the whole sheet."""
    h, w, _ = rgb.shape
    edge = np.concatenate([rgb[:3].reshape(-1, 3), rgb[-3:].reshape(-1, 3),
                           rgb[:, :3].reshape(-1, 3), rgb[:, -3:].reshape(-1, 3)])
    return tuple(int(v) for v in np.median(edge, axis=0))


def remove_background(img, bg):
    """RGBA out. Pixels close to bg AND connected to the border become transparent,
    with a soft ramp on the boundary and colour de-spill so no pink fringe remains."""
    a = np.asarray(img.convert("RGBA")).astype(np.float32)
    rgb, alpha0 = a[..., :3], a[..., 3]
    if alpha0.min() < 250:  # already has real transparency
        return Image.fromarray(a.astype(np.uint8), "RGBA"), "alpha"
    dist = np.sqrt(((rgb - np.array(bg, dtype=np.float32)) ** 2).sum(-1))
    lo, hi = 45.0, 110.0
    near = dist < hi
    labels, n = ndimage.label(near)
    border = np.unique(np.concatenate([labels[0], labels[-1], labels[:, 0], labels[:, -1]]))
    border = border[border > 0]
    bgmask = np.isin(labels, border)
    # also drop enclosed background holes (e.g. between legs) that are very close to the key
    holes = (dist < lo) & ~bgmask
    hl, hn = ndimage.label(holes)
    if hn:
        sizes = ndimage.sum(holes, hl, range(1, hn + 1))
        for i, s in enumerate(sizes, start=1):
            if s >= 12:
                bgmask |= hl == i
    alpha = np.where(bgmask, np.clip((dist - lo) / (hi - lo), 0, 1), 1.0)
    # de-spill: pull the key colour out of semi-transparent / edge pixels
    edge = ndimage.binary_dilation(bgmask, iterations=2) & ~(bgmask & (alpha == 0))
    key = np.array(bg, dtype=np.float32)
    spill = np.clip(1.0 - dist / 160.0, 0, 1)[..., None]
    corrected = np.where(edge[..., None], (rgb - key * spill * 0.85) / np.maximum(1 - spill * 0.85, 0.15), rgb)
    rgb2 = np.clip(corrected, 0, 255)
    out = np.dstack([rgb2, alpha * 255]).astype(np.uint8)
    out[alpha == 0] = 0
    return Image.fromarray(out, "RGBA"), "chroma"


# ---------------------------------------------------------------------- frames

def split_cells(img):
    w, h = img.size
    cw, ch = w // GRID, h // GRID
    if cw < 16 or ch < 16:
        raise SystemExit("sheet too small")
    return [img.crop(((i % GRID) * cw, (i // GRID) * ch, (i % GRID) * cw + cw, (i // GRID) * ch + ch))
            for i in range(FRAMES)]


def bbox_alpha(im, thr=40):
    a = np.asarray(im)[..., 3]
    ys, xs = np.where(a > thr)
    if len(xs) == 0:
        return None
    return xs.min(), ys.min(), xs.max() + 1, ys.max() + 1


def normalise(cells, cell, margin):
    """Common scale for all frames; feet on a shared baseline, horizontally centred."""
    boxes = [bbox_alpha(c) for c in cells]
    problems = []
    for i, b in enumerate(boxes):
        if b is None:
            problems.append(f"frame {i}: empty")
    if problems:
        return None, problems, boxes
    # drop tiny stray specks: keep only the largest connected blob per frame
    cleaned = []
    for c, b in zip(cells, boxes):
        arr = np.asarray(c).copy()
        lab, n = ndimage.label(arr[..., 3] > 40)
        if n > 1:
            sizes = ndimage.sum(np.ones_like(lab), lab, range(1, n + 1))
            keep = {i + 1 for i, s in enumerate(sizes) if s >= 0.05 * max(sizes)}
            mask = np.isin(lab, list(keep))
            arr[~mask] = 0
        cleaned.append(Image.fromarray(arr, "RGBA"))
    boxes = [bbox_alpha(c) for c in cleaned]
    maxw = max(b[2] - b[0] for b in boxes)
    maxh = max(b[3] - b[1] for b in boxes)
    scale = min((cell - 2 * margin) / maxw, (cell - margin - 2) / maxh)
    out = []
    for c, b in zip(cleaned, boxes):
        crop = c.crop(b)
        nw, nh = max(1, round(crop.width * scale)), max(1, round(crop.height * scale))
        crop = crop.resize((nw, nh), Image.LANCZOS)
        frame = Image.new("RGBA", (cell, cell), (0, 0, 0, 0))
        frame.paste(crop, ((cell - nw) // 2, cell - 2 - nh), crop)
        out.append(frame)
    return out, problems, boxes


def quality_checks(cells, boxes, raw_cells):
    msgs = []
    areas = []
    for i, c in enumerate(cells):
        a = np.asarray(c)[..., 3]
        areas.append(int((a > 40).sum()))
    med = float(np.median(areas))
    for i, ar in enumerate(areas):
        if ar < 0.35 * med:
            msgs.append(f"frame {i}: much smaller than the others ({ar} vs median {int(med)} px) - redo this frame")
        elif ar > 2.6 * med:
            msgs.append(f"frame {i}: much bigger than the others - redo this frame")
    # leftover key colour
    for i, c in enumerate(cells):
        arr = np.asarray(c).astype(int)
        vis = arr[..., 3] > 200
        if vis.sum():
            mag = ((arr[..., 0] > 200) & (arr[..., 2] > 200) & (arr[..., 1] < 70) & vis).sum()
            if mag > 0.02 * vis.sum():
                msgs.append(f"frame {i}: leftover magenta background/fringe ({mag} px)")
    return msgs


# ------------------------------------------------------------------- animation

def sequence_frames(order, cells):
    return [cells[i] for i in order]


def make_preview(cells, path, bg=(235, 235, 235)):
    seqs = [[0, 1, 2, 3] * 2, [4, 5, 6, 7] * 2, [8, 9] * 4, [10, 11] * 4, [12, 13] * 4, [14, 15] * 4]
    order = [i for s in seqs for i in s]
    frames = []
    for i in order:
        bgim = Image.new("RGBA", cells[0].size, bg + (255,))
        bgim.alpha_composite(cells[i])
        frames.append(bgim.convert("P", palette=Image.ADAPTIVE))
    frames[0].save(path, save_all=True, append_images=frames[1:], duration=150, loop=0, disposal=2)


def make_contact(cells, path):
    c = cells[0].width
    sheet = Image.new("RGBA", (c * GRID, c * GRID), (0, 0, 0, 0))
    for i, f in enumerate(cells):
        sheet.paste(f, ((i % GRID) * c, (i // GRID) * c))
    sheet.save(path)
    check = Image.new("RGBA", sheet.size, (225, 225, 225, 255))
    check.alpha_composite(sheet)
    check.convert("RGB").save(path.replace(".png", "_preview.png"))
    return sheet


def main():
    ap = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    ap.add_argument("sheet")
    ap.add_argument("outdir")
    ap.add_argument("--name", default="Pet")
    ap.add_argument("--cell", type=int, default=96)
    ap.add_argument("--bg", default="auto")
    a = ap.parse_args()

    img = Image.open(a.sheet).convert("RGBA")
    rgb = np.asarray(img.convert("RGB"))
    bg = parse_color(a.bg) if a.bg != "auto" else estimate_bg(rgb)
    keyed, mode = remove_background(img, bg)
    print(f"background: {mode}, key colour {bg}, sheet {img.size}")
    cells_raw = split_cells(keyed)
    cells, problems, boxes = normalise(cells_raw, a.cell, margin=4)
    if cells is None:
        print("FAILED:", *problems, sep="\n  ")
        sys.exit(2)
    msgs = quality_checks(cells, boxes, cells_raw)
    os.makedirs(a.outdir, exist_ok=True)
    sheet = make_contact(cells, os.path.join(a.outdir, "sprite.png"))
    cells[4].save(os.path.join(a.outdir, "icon.png"))
    with open(os.path.join(a.outdir, "animations.xml"), "w", encoding="utf-8", newline="\n") as f:
        f.write(build_xml(sheet, a.name, cell=a.cell))
    make_preview(cells, os.path.join(a.outdir, "preview.gif"))
    print(f"wrote {a.outdir}/animations.xml sprite.png ({sheet.size[0]}x{sheet.size[1]}) icon.png preview.gif")
    if msgs:
        print("QUALITY WARNINGS:")
        for m in msgs:
            print("  -", m)
        sys.exit(2)
    print("quality: OK")


if __name__ == "__main__":
    main()
